using System.Net;
using System.Text;
using System.Text.Json;
using FluentAssertions;
using Microsoft.Extensions.Logging.Abstractions;
using Neuroset.Application;
using Neuroset.Domain;
using Neuroset.Providers;

namespace Neuroset.Tests;

public sealed class ProviderTests
{
    private static ConnectionProfile Connection=>new(){Name="test",BaseUrl="https://example.test/v1",ApiKeySecretId="secret",Model="model",TimeoutSeconds=10};
    [Fact]public async Task Streaming_Parses_Text_ToolCalls_And_Usage(){var sse="data: {\"choices\":[{\"delta\":{\"content\":\"Hi \"}}]}\n\n"+"data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,\"id\":\"c1\",\"function\":{\"name\":\"echo\",\"arguments\":\"{\\\"value\\\":\\\"x\\\"}\"}}]}}]}\n\n"+"data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"tool_calls\"}],\"usage\":{\"prompt_tokens\":2,\"completion_tokens\":3,\"total_tokens\":5}}\n\n"+"data: [DONE]\n\n";var client=new HttpClient(new DelegateHttpHandler(_=>new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(sse,Encoding.UTF8,"text/event-stream")}));var provider=new OpenAiCompatibleProvider(client,new MemorySecretStore(),NullLogger<OpenAiCompatibleProvider>.Instance);var events=new List<ModelEvent>();await foreach(var item in provider.StreamAsync(new(Connection,[new(MessageRole.User,"hello")],[],true)))events.Add(item);events.OfType<TextDeltaEvent>().Select(x=>x.Delta).Should().Contain("Hi ");events.OfType<ToolCallStartedEvent>().Should().ContainSingle(x=>x.CallId=="c1"&&x.Name=="echo");events.OfType<ToolCallArgumentsEvent>().Should().ContainSingle();events.OfType<UsageEvent>().Select(x=>x.Usage.TotalTokens).Should().Contain(5);}
    [Fact]public async Task Complete_Parses_Normal_Response(){var json="""{"choices":[{"message":{"content":"done","tool_calls":[]},"finish_reason":"stop"}],"usage":{"prompt_tokens":1,"completion_tokens":1,"total_tokens":2}}""";var client=new HttpClient(new DelegateHttpHandler(_=>new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(json,Encoding.UTF8,"application/json")}));var provider=new OpenAiCompatibleProvider(client,new MemorySecretStore(),NullLogger<OpenAiCompatibleProvider>.Instance);var result=await provider.CompleteAsync(new(Connection,[new(MessageRole.User,"hello")],[],false));result.Content.Should().Be("done");result.Usage!.TotalTokens.Should().Be(2);}
    [Fact]public async Task Complete_Sends_Trailing_Assistant_Prefill_As_Standard_Message(){string? body=null;var json="""{"choices":[{"message":{"content":"OK"},"finish_reason":"stop"}]}""";var client=new HttpClient(new DelegateHttpHandler(message=>{body=message.Content!.ReadAsStringAsync().GetAwaiter().GetResult();return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(json,Encoding.UTF8,"application/json")};}));var provider=new OpenAiCompatibleProvider(client,new MemorySecretStore(),NullLogger<OpenAiCompatibleProvider>.Instance);await provider.CompleteAsync(new(Connection,[new(MessageRole.User,"marker"),new(MessageRole.Assistant,"PREFILL_")],[],false));body.Should().Contain("\"role\":\"assistant\"").And.Contain("PREFILL_");}
    [Fact]public async Task Complete_Sends_Full_Generation_Profile(){string? body=null;var json="""{"choices":[{"message":{"content":"OK"},"finish_reason":"stop"}]}""";var client=new HttpClient(new DelegateHttpHandler(message=>{body=message.Content!.ReadAsStringAsync().GetAwaiter().GetResult();return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(json,Encoding.UTF8,"application/json")};}));var provider=new OpenAiCompatibleProvider(client,new MemorySecretStore(),NullLogger<OpenAiCompatibleProvider>.Instance);var generation=new GenerationSettings{Temperature=1.2,TopP=.75,MaxTokens=777,PresencePenalty=.3,FrequencyPenalty=-.2,Seed=42,StopSequences=["STOP"]};await provider.CompleteAsync(new(Connection,[new(MessageRole.User,"marker")],[],false,Generation:generation));using var document=JsonDocument.Parse(body!);var root=document.RootElement;root.GetProperty("temperature").GetDouble().Should().Be(1.2);root.GetProperty("top_p").GetDouble().Should().Be(.75);root.GetProperty("max_tokens").GetInt32().Should().Be(777);root.GetProperty("presence_penalty").GetDouble().Should().Be(.3);root.GetProperty("frequency_penalty").GetDouble().Should().Be(-.2);root.GetProperty("seed").GetInt32().Should().Be(42);root.GetProperty("stop")[0].GetString().Should().Be("STOP");}
    [Fact]public async Task Models_Endpoint_Is_Supported(){Uri? requested=null;var client=new HttpClient(new DelegateHttpHandler(message=>{requested=message.RequestUri;return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"data\":[{\"id\":\"b\"},{\"id\":\"a\"}]}")};}));var provider=new OpenAiCompatibleProvider(client,new MemorySecretStore(),NullLogger<OpenAiCompatibleProvider>.Instance);(await provider.ListModelsAsync(Connection)).Should().Equal("a","b");requested!.AbsoluteUri.Should().Be("https://example.test/v1/models");}
    [Fact]public async Task Complete_Sends_Reasoning_Effort(){string? body=null;var json="""{"choices":[{"message":{"content":"OK"},"finish_reason":"stop"}]}""";var client=new HttpClient(new DelegateHttpHandler(message=>{body=message.Content!.ReadAsStringAsync().GetAwaiter().GetResult();return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(json,Encoding.UTF8,"application/json")};}));var provider=new OpenAiCompatibleProvider(client,new MemorySecretStore(),NullLogger<OpenAiCompatibleProvider>.Instance);await provider.CompleteAsync(new(Connection,[new(MessageRole.User,"marker")],[],false,ReasoningEffort:ReasoningEffort.XHigh));using var document=JsonDocument.Parse(body!);document.RootElement.GetProperty("reasoning_effort").GetString().Should().Be("xhigh");}
    [Fact]public async Task Unsupported_Max_Reasoning_Falls_Back_To_XHigh(){var bodies=new List<string>();var calls=0;var success="""{"choices":[{"message":{"content":"OK"},"finish_reason":"stop"}]}""";var unsupported="""{"error":{"message":"Unsupported value for reasoning_effort"}}""";var client=new HttpClient(new DelegateHttpHandler(message=>{calls++;bodies.Add(message.Content!.ReadAsStringAsync().GetAwaiter().GetResult());return calls==1?new HttpResponseMessage(HttpStatusCode.BadRequest){Content=new StringContent(unsupported,Encoding.UTF8,"application/json")}:new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(success,Encoding.UTF8,"application/json")};}));var provider=new OpenAiCompatibleProvider(client,new MemorySecretStore(),NullLogger<OpenAiCompatibleProvider>.Instance);(await provider.CompleteAsync(new(Connection,[new(MessageRole.User,"marker")],[],false,ReasoningEffort:ReasoningEffort.Max))).Content.Should().Be("OK");calls.Should().Be(2);using var first=JsonDocument.Parse(bodies[0]);using var second=JsonDocument.Parse(bodies[1]);first.RootElement.GetProperty("reasoning_effort").GetString().Should().Be("max");second.RootElement.GetProperty("reasoning_effort").GetString().Should().Be("xhigh");}
}
